// lifeshot/theme — wholesale regen, `key=#hex` per line. lifeshot reads it
// each time it runs (it is a one-shot overlay); it never parses
// theme.toml itself, same arrangement as lifenote.

use crate::theme::{hash, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    format!(
        "# lifeshot colours. Generated by lifeconf.\n\
         # Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file.\n\
         surface={}\n\
         border={}\n\
         text={}\n\
         accent={}\n\
         warn={}\n",
        hash(&p.surface),
        hash(&p.border),
        hash(&p.text),
        hash(&p.accent),
        hash(&p.warn),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn emits_palette_roles_as_hex() {
        let t = Theme::default();
        let s = render(&t);
        assert!(s.contains("accent=#a4c94b"));
        assert!(s.contains("surface=#171a14"));
    }
}
